// This is a simple interface which specifies echo.Route addition functions which
// are present on both echo.Echo and echo.Group, since we want to allow using
// either of them for path registration
type EchoRouter interface {
	CONNECT(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	DELETE(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	GET(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	HEAD(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	OPTIONS(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	PATCH(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	POST(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	PUT(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	TRACE(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
}

// RegisterHandlers adds each server route to the EchoRouter.
func RegisterHandlers(router EchoRouter, si ServerInterface) {
	RegisterHandlersWithBaseURL(router, si, "")
}

// Registers handlers, and prepends BaseURL to the paths, so that the paths
// can be served under a prefix.
func RegisterHandlersWithBaseURL(router EchoRouter, si ServerInterface, baseURL string) {

	wrapper := ServerInterfaceWrapper{
		Handler: si,
	}

	router.POST(baseURL+"/auth/login", wrapper.LoginUser)
	router.POST(baseURL+"/auth/logout", wrapper.LogoutUser)
	router.POST(baseURL+"/auth/register", wrapper.RegisterUser)
	router.GET(baseURL+"/auth/tokens", wrapper.ListTokens)
	router.POST(baseURL+"/auth/tokens", wrapper.CreateToken)
	router.DELETE(baseURL+"/auth/tokens/:id", wrapper.RevokeToken)
	router.GET(baseURL+"/budgets", wrapper.ListBudgets)
	router.POST(baseURL+"/budgets", wrapper.CreateBudget)
	router.PATCH(baseURL+"/budgets/:budgetId", wrapper.UpdateBudget)
	router.GET(baseURL+"/budgets/:budgetId/accounts", wrapper.ListAccounts)
	router.POST(baseURL+"/budgets/:budgetId/accounts", wrapper.CreateAccount)
	router.POST(baseURL+"/budgets/:budgetId/accounts/:accountId/import-csv", wrapper.ImportAccountCsv)
	router.GET(baseURL+"/budgets/:budgetId/buckets", wrapper.ListBuckets)
	router.POST(baseURL+"/budgets/:budgetId/buckets", wrapper.CreateBucket)
	router.POST(baseURL+"/budgets/:budgetId/buckets/:id/targets", wrapper.CreateTarget)
	router.POST(baseURL+"/budgets/:budgetId/integrations/:integrationId/link-account", wrapper.LinkIntegrationAccount)
	router.POST(baseURL+"/budgets/:budgetId/integrations/:integrationId/sync", wrapper.SyncIntegration)
	router.POST(baseURL+"/budgets/:budgetId/invitations", wrapper.InviteBudgetMember)
	router.GET(baseURL+"/budgets/:budgetId/matching-rules", wrapper.ListMatchingRules)
	router.POST(baseURL+"/budgets/:budgetId/matching-rules", wrapper.CreateMatchingRule)
	router.GET(baseURL+"/budgets/:budgetId/parties", wrapper.ListParties)
	router.POST(baseURL+"/budgets/:budgetId/parties", wrapper.CreateParty)
	router.PUT(baseURL+"/budgets/:budgetId/parties/:id", wrapper.UpdateParty)
	router.GET(baseURL+"/budgets/:budgetId/parties/:id/cashflow", wrapper.GetPartyCashflow)
	router.GET(baseURL+"/budgets/:budgetId/raw-transactions", wrapper.ListRawTransactions)
	router.GET(baseURL+"/budgets/:budgetId/reports/age-of-money", wrapper.GetAgeOfMoneyReport)
	router.GET(baseURL+"/budgets/:budgetId/reports/balance-forecast", wrapper.GetBalanceForecastReport)
	router.GET(baseURL+"/budgets/:budgetId/reports/budget-analysis", wrapper.GetBudgetAnalysisReport)
	router.GET(baseURL+"/budgets/:budgetId/reports/income-vs-expense", wrapper.GetIncomeVsExpenseReport)
	router.POST(baseURL+"/budgets/:budgetId/reports/monte-carlo/simulate", wrapper.SimulateMonteCarlo)
	router.GET(baseURL+"/budgets/:budgetId/reports/net-worth", wrapper.GetNetWorthReport)
	router.GET(baseURL+"/budgets/:budgetId/reports/party-cashflow", wrapper.GetPartyCashflowReport)
	router.GET(baseURL+"/budgets/:budgetId/reports/sankey", wrapper.GetSankeyReport)
	router.GET(baseURL+"/budgets/:budgetId/reports/saved", wrapper.ListSavedReports)
	router.POST(baseURL+"/budgets/:budgetId/reports/saved", wrapper.CreateSavedReport)
	router.PUT(baseURL+"/budgets/:budgetId/reports/saved/:id", wrapper.UpdateSavedReport)
	router.GET(baseURL+"/budgets/:budgetId/reports/spending-breakdown", wrapper.GetSpendingBreakdownReport)
	router.GET(baseURL+"/budgets/:budgetId/reports/spending-trends", wrapper.GetSpendingTrendsReport)
	router.POST(baseURL+"/budgets/:budgetId/structure/generate-ai", wrapper.GenerateBudgetStructureAI)
	router.POST(baseURL+"/budgets/:budgetId/structure/import", wrapper.ImportBudgetStructure)
	router.POST(baseURL+"/budgets/:budgetId/targets/generate-formula", wrapper.GenerateFormula)
	router.POST(baseURL+"/budgets/:budgetId/targets/validate-formula", wrapper.ValidateFormula)
	router.POST(baseURL+"/budgets/:budgetId/targets/:id/fund", wrapper.FundTarget)
	router.GET(baseURL+"/budgets/:budgetId/transactions", wrapper.ListBudgetTransactions)
	router.POST(baseURL+"/budgets/:budgetId/transactions", wrapper.CreateBudgetTransaction)
	router.POST(baseURL+"/budgets/:budgetId/transactions/resolve", wrapper.ResolveTransactions)
	router.GET(baseURL+"/budgets/:budgetId/view/horizon", wrapper.GetHorizonView)
	router.GET(baseURL+"/budgets/:budgetId/:entityType/:id/history", wrapper.GetEntityHistory)
	router.POST(baseURL+"/budgets/:budgetId/:entityType/:id/restore", wrapper.RestoreEntityVersion)
	router.GET(baseURL+"/exchange-rates", wrapper.GetExchangeRates)
	router.POST(baseURL+"/exchange-rates/sync", wrapper.SyncExchangeRates)
	router.GET(baseURL+"/integrations/providers", wrapper.ListIntegrationProviders)
	router.GET(baseURL+"/integrations/:provider/callback", wrapper.ProviderCallback)
	router.POST(baseURL+"/integrations/:provider/connect", wrapper.ConnectProvider)
	router.POST(baseURL+"/invitations/:token/accept", wrapper.AcceptInvitation)
	router.GET(baseURL+"/users/me", wrapper.GetCurrentUser)
	router.PUT(baseURL+"/users/me", wrapper.UpdateCurrentUser)

}

